import re

def is_palindrome(text: str) -> bool:
    cleaned_text: str = re.sub(r'[^a-zA-Z0-9]', '', text).lower()
    return cleaned_text == cleaned_text[::-1]

def process_texts(texts: list[str]) -> dict[str, bool]:
    results: dict[str, bool] = {}
    for t in texts:
        results[t] = is_palindrome(t)
    return results

def get_palindrome_count(texts: list[str]) -> int:
    count: int = 0
    for t in texts:
        if is_palindrome(t):
            count += 1
    return count

def filter_palindromes(texts: list[str]) -> list[str]:
    palindromes: list[str] = [t for t in texts if is_palindrome(t)]
    return palindromes

def main() -> None:
    test_strings: list[str] = ["Racecar", "Hello World", "A man, a plan, a canal: Panama", "No lemon, no melon", "Python"]

    for s in test_strings:
        print(f"'{s}' is a palindrome: {is_palindrome(s)}")

    processing_results: dict[str, bool] = process_texts(test_strings)
    print(f"\nProcessing results: {processing_results}")

    num_palindromes: int = get_palindrome_count(test_strings)
    print(f"\nNumber of palindromes found: {num_palindromes}")

    filtered: list[str] = filter_palindromes(test_strings)
    print(f"\nFiltered palindromes: {filtered}")

if __name__ == '__main__':
    main()

