def validate_email(email: str) -> bool:
    if '@' not in email or '.' not in email:
        return False

    parts: list[str] = email.split('@')
    if len(parts) != 2:
        return False

    local_part: str = parts[0]
    domain_part: str = parts[1]

    if not local_part or not domain_part:
        return False

    if '.' not in domain_part:
        return False

    domain_subparts: list[str] = domain_part.split('.')
    if any(not part for part in domain_subparts):
        return False

    at_index: int = email.find('@')
    dot_index: int = email.find('.', at_index)

    return at_index < dot_index and dot_index != -1

def run_tests() -> dict[str, bool]:
    test_cases: list[tuple[str, bool]] = [
        ("test@example.com", True),
        ("invalid-email", False),
        ("a@b.c", True),
        ("@example.com", False),
        ("test@", False),
        ("test.com", False),
        ("test@.com", False),
        ("test@example.", False),
        ("test@example.c", True),
        ("a@b.c.d", True)
    ]

    results: dict[str, bool] = {}
    for email_str, expected in test_cases:
        actual: bool = validate_email(email_str)
        results[email_str] = actual == expected
    return results

if __name__ == '__main__':
    test_results: dict[str, bool] = run_tests()
    for email, passed in test_results.items():
        print(f"'{email}' passed: {passed}")

import math

def geometric_mean(numbers: list[float]) -> float:
    if not numbers:
        raise ValueError("Input list cannot be empty.")

    product: float = 1.0
    for num in numbers:
        if num <= 0:
            raise ValueError("All numbers must be positive.")
        product *= num

    n: int = len(numbers)
    return product ** (1 / n)

def calculate_stats(data: dict[str, list[float]]) -> dict[str, float]:
    results: dict[str, float] = {}
    for key, values in data.items():
        try:
            mean: float = geometric_mean(values)
            results[key] = mean
        except ValueError as e:
            print(f"Error calculating geometric mean for '{key}': {e}")
            results[key] = float('nan') # Represents Not a Number
    return results

if __name__ == '__main__':
    test_cases: list[tuple[list[float], float]] = [
        ([2.0, 8.0], 4.0),
        ([1.0, 1.0, 1.0], 1.0),
        ([3.0, 9.0, 27.0], 9.0),
        ([0.5, 2.0], 1.0)
    ]

    for input_list, expected_output in test_cases:
        actual_output: float = geometric_mean(input_list)
        print(f"geometric_mean({input_list}) = {actual_output} (Expected: {expected_output})")
        assert math.isclose(actual_output, expected_output), f"Test failed for {input_list}"

    sample_data: dict[str, list[float]] = {
        "set_a": [10.0, 100.0, 1000.0],
        "set_b": [2.0, 4.0, 8.0, 16.0],
        "set_c": [1.0],
        "set_d": [],
        "set_e": [5.0, -1.0]
    }
    processed_results: dict[str, float] = calculate_stats(sample_data)
    print("\nProcessed Results:")
    for label, g_mean in processed_results.items():
        print(f"{label}: {g_mean}")

