def simulate_queue(operations: List[Tuple[str, Union[int, None]]]) -> List[int]:
    q: Deque[int] = deque()
    for operation, value in operations:
        if operation == 'enqueue':
            if value is not None:
                q.append(value)
        elif operation == 'dequeue':
            if q:
                q.popleft()
    return list(q)

