def rock_paper_scissors(player1_choice: str, player2_choice: str) -> str:
    rules: dict[str, str] = {
        'rock': 'scissors',
        'paper': 'rock',
        'scissors': 'paper'
    }

    if player1_choice == player2_choice:
        return "It's a tie!"
    elif rules[player1_choice] == player2_choice:
        return "Player 1 wins!"
    else:
        return "Player 2 wins!"

def run_tests() -> list[str]:
    test_cases: list[tuple[str, str, str]] = [
        ('rock', 'scissors', 'Player 1 wins!'),
        ('paper', 'rock', 'Player 1 wins!'),
        ('scissors', 'paper', 'Player 1 wins!'),
        ('rock', 'paper', 'Player 2 wins!'),
        ('paper', 'scissors', 'Player 2 wins!'),
        ('scissors', 'rock', 'Player 2 wins!'),
        ('rock', 'rock', "It's a tie!"),
        ('paper', 'paper', "It's a tie!"),
        ('scissors', 'scissors', "It's a tie!")
    ]
    results: list[str] = []
    for p1_choice, p2_choice, expected_output in test_cases:
        actual_output: str = rock_paper_scissors(p1_choice, p2_choice)
        assert actual_output == expected_output, f"Input: ({p1_choice}, {p2_choice}), Expected: {expected_output}, Got: {actual_output}"
        results.append(f"Test passed for ({p1_choice}, {p2_choice})")
    return results

if __name__ == '__main__':
    all_test_results: list[str] = run_tests()
    for res in all_test_results:
        print(res)

