def portfolio_value(stocks: dict[str, int], prices: dict[str, float]) -> float:
    total_value: float = 0.0
    for ticker, quantity in stocks.items():
        if ticker in prices:
            total_value += quantity * prices[ticker]
    return total_value

def calculate_average_price(prices_list: list[float]) -> float:
    if not prices_list:
        return 0.0
    return sum(prices_list) / len(prices_list)

def get_expensive_stocks(stocks: dict[str, int], prices: dict[str, float], threshold: float) -> list[str]:
    expensive_tickers: list[str] = []
    for ticker in stocks:
        if ticker in prices and prices[ticker] > threshold:
            expensive_tickers.append(ticker)
    return expensive_tickers

