def decimal_to_binary(decimal_int: int) -> str:
    if decimal_int == 0:
        return '0'

    binary_digits: list[str] = []
    current_number: int = decimal_int

    while current_number > 0:
        remainder: int = current_number % 2
        binary_digits.append(str(remainder))
        current_number //= 2

    return "".join(binary_digits[::-1])

def test_decimal_to_binary() -> dict[str, str]:
    test_cases: dict[int, str] = {
        0: '0',
        1: '1',
        2: '10',
        3: '11',
        10: '1010',
        11: '1011',
        16: '10000',
        255: '11111111'
    }
    results: dict[str, str] = {}
    for input_val, expected_output in test_cases.items():
        actual_output: str = decimal_to_binary(input_val)
        status: str = "Passed" if actual_output == expected_output else "Failed"
        results[f"Input: {input_val}, Expected: {expected_output}, Got: {actual_output}"] = status
    return results

if __name__ == "__main__":
