def nth_fibonacci(n: int) -> int:
    """
    Calculates the Nth Fibonacci number.
    The sequence starts with 0, 1, 1, 2...
    """
    if n < 0:
        raise ValueError("Input must be a non-negative integer.")
    if n == 0:
        return 0
    elif n == 1:
        return 1
    else:
        a: int = 0
        b: int = 1
        for _ in range(2, n + 1):
            a, b = b, a + b
        return b

def get_fibonacci_sequence_up_to_n(n: int) -> list[int]:
    """
    Generates a list of Fibonacci numbers up to the Nth term.
    """
    if n < 0:
        raise ValueError("Input must be a non-negative integer.")
    if n == 0:
        return [0]
    elif n == 1:
        return [0, 1]

    sequence: list[int] = [0, 1]
    while len(sequence) <= n:
        sequence.append(sequence[-1] + sequence[-2])
    return sequence

def fibonacci_map(limit: int) -> dict[int, int]:
    """
    Creates a dictionary mapping n to the nth Fibonacci number up to a given limit.
    """
    fib_map: dict[int, int] = {}
    if limit < 0:
        return fib_map
    for i in range(limit + 1):
        fib_map[i] = nth_fibonacci(i)
    return fib_map

