def decrypt_caesar(text: str, shift: int) -> str:
    decrypted_chars: list[str] = []
    alphabet_size: int = 26
    for char_code in map(ord, text):
        if 'a' <= chr(char_code) <= 'z':
            decrypted_char_code: int = (char_code - ord('a') - shift + alphabet_size) % alphabet_size + ord('a')
            decrypted_chars.append(chr(decrypted_char_code))
        else:
            decrypted_chars.append(chr(char_code))
    return "".join(decrypted_chars)

def example_usage() -> list[str]:
    test_cases: list[tuple[str, int, str]] = [
        ('khoor', 3, 'hello'),
        ('wkhuh', 3, 'there'),
        ('abc', 0, 'abc'),
        ('xyz', 1, 'wxy'),
        ('a', 26, 'a')
    ]
    results: list[str] = []
    for encrypted_text, shift_value, expected_output in test_cases:
        actual_output: str = decrypt_caesar(encrypted_text, shift_value)
        results.append(f"Input: '{encrypted_text}', Shift: {shift_value}, Expected: '{expected_output}', Got: '{actual_output}'")
    return results

if __name__ == '__main__':
