import datetime

def days_since_epoch(date_str: str) -> int:
    epoch_date: datetime.date = datetime.date(1970, 1, 1)
    year: int = int(date_str[0:4])
    month: int = int(date_str[5:7])
    day: int = int(date_str[8:10])
    target_date: datetime.date = datetime.date(year, month, day)
    delta: datetime.timedelta = target_date - epoch_date
    return delta.days

def calculate_days_for_dates(date_strings: list[str]) -> dict[str, int]:
    results: dict[str, int] = {}
    for date_str_item in date_strings:
        days: int = days_since_epoch(date_str_item)
        results[date_str_item] = days
    return results

if __name__ == '__main__':
    test_dates: list[str] = ['1970-01-01', '1970-01-02', '2023-10-27']
    output_dict: dict[str, int] = calculate_days_for_dates(test_dates)
