        ([1.0], [10.0], 1.0),
        ([100.0, 0.0], [0.25, 0.75], 25.0)
    ]

    for values, weights, expected in test_cases:
        result: float = weighted_average(values, weights)
        print(f"weighted_average({values}, {weights}) -> {result}, Expected: {expected}, Match: {result == expected}")

if __name__ == "__main__":
