def is_divisible_by_3_and_5(number: int) -> bool:
    """
    Checks if a given integer is divisible by both 3 and 5.
    """
    return number % 3 == 0 and number % 5 == 0

def process_numbers(numbers_list: list[int]) -> dict[int, bool]:
    """
    Processes a list of numbers and returns a dictionary indicating
    if each number is divisible by both 3 and 5.
    """
    results: dict[int, bool] = {}
    for num in numbers_list:
        results[num] = is_divisible_by_3_and_5(num)
    return results

def get_divisible_numbers(numbers: list[int]) -> list[int]:
    """
    Returns a list of numbers from the input that are divisible by both 3 and 5.
    """
    divisible_nums: list[int] = []
    for n in numbers:
        if is_divisible_by_3_and_5(n):
            divisible_nums.append(n)
    return divisible_nums

def main() -> None:
    test_cases: list[int] = [15, 10, 30, 7, 0, -15]
    for case in test_cases:
        print(f"{case} divisible by 3 and 5: {is_divisible_by_3_and_5(case)}")

    processed_results: dict[int, bool] = process_numbers(test_cases)
    print("Processed results:", processed_results)

    only_divisible: list[int] = get_divisible_numbers(test_cases)
    print("Only divisible numbers:", only_divisible)

if __name__ == "__main__":
    main()

def minutes_to_hh_mm(total_minutes: int) -> str:
    """Converts a total number of minutes into a 'HH:MM' string format."""
    hours: int = total_minutes // 60
    minutes: int = total_minutes % 60

    parts: list[str] = [str(hours), str(minutes)]

    formatted_parts: list[str] = []
    for part in parts:
        if len(part) == 1:
            formatted_parts.append('0' + part)
        else:
            formatted_parts.append(part)

    return ":".join(formatted_parts)

