def find_duplicate(numbers: list[int]) -> int:
    seen: dict[int, int] = {}
    for num in numbers:
        if num in seen:
            return num
        seen[num] = 1
    return -1 # Should not be reached based on problem description.

def find_duplicate_math(numbers: list[int]) -> int:
    n: int = len(numbers) - 1
    expected_sum: int = n * (n + 1) // 2
    actual_sum: int = sum(numbers)
    return actual_sum - expected_sum

def find_duplicate_xor(numbers: list[int]) -> int:
    xor_sum: int = 0
    max_val: int = len(numbers) - 1
    for num in numbers:
        xor_sum ^= num
    for i in range(1, max_val + 1):
        xor_sum ^= i
    return xor_sum

