import random

def roll_die(num_sides: int) -> int:
    """Simulates a single roll of an N-sided die."""
    if num_sides < 1:
        raise ValueError("Number of sides must be at least 1.")
    return random.randint(1, num_sides)

def simulate_rolls(num_rolls: int, num_sides: int) -> list[int]:
    """Simulates multiple die rolls and returns a list of results."""
    results: list[int] = []
    for _ in range(num_rolls):
        results.append(roll_die(num_sides))
    return results

def get_roll_counts(rolls: list[int]) -> dict[int, int]:
    """Counts the occurrences of each roll result."""
    counts: dict[int, int] = {}
    for roll_result in rolls:
        counts[roll_result] = counts.get(roll_result, 0) + 1
    return counts

def main() -> None:
    sides: int = 6
    number_of_simulations: int = 10

    simulation_results: list[int] = simulate_rolls(number_of_simulations, sides)
    print(f"Results of {number_of_simulations} rolls of a {sides}-sided die: {simulation_results}")

    roll_frequencies: dict[int, int] = get_roll_counts(simulation_results)
    print(f"Roll frequencies: {roll_frequencies}")

if __name__ == "__main__":
    main()

