def has_overlap(task1_start: int, task1_end: int, task2_start: int, task2_end: int) -> bool:
    """
    Detects if two tasks, each with a start and end time, overlap.
    Times are integers representing hours in a 24-hour format.
    """
    task1_interval: tuple[int, int] = (task1_start, task1_end)
    task2_interval: tuple[int, int] = (task2_start, task2_end)

    if task1_interval[1] <= task2_interval[0] or task2_interval[1] <= task1_interval[0]:
        return False
    return True

def get_task_data(task_id: str) -> dict[str, int]:
    """
    Simulates getting task start and end times from a data source.
    """
    if task_id == "A":
        return {"start": 9, "end": 12}
    elif task_id == "B":
        return {"start": 11, "end": 14}
    elif task_id == "C":
        return {"start": 9, "end": 10}
    elif task_id == "D":
        return {"start": 10, "end": 12}
    return {"start": 0, "end": 0}

def main() -> None:
    tasks: list[str] = ["A", "B", "C", "D"]
