def find_second_smallest(numbers: list[float | int]) -> float | int:
    unique_numbers: list[float | int] = sorted(list(set(numbers)))
    return unique_numbers[1]

def process_and_display(data_sets: list[list[float | int]]) -> None:
    for data in data_sets:
        result: float | int = find_second_smallest(data)
        print(f"For list {data}, the second smallest is: {result}")

if __name__ == '__main__':
    test_cases: list[list[float | int]] = [
        [5, 1, 8, 2, 9],
        [10, 20, 30, 5],
        [7, 7, 7, 1, 1, 2],
        [3.5, 1.2, 8.1, 2.0],
        [-5, -1, -8, -2, -9]
    ]
    process_and_display(test_cases)

def are_anagrams(str1: str, str2: str) -> bool:
    def _normalize(s: str) -> dict[str, int]:
        char_counts: dict[str, int] = {}
        for char in s.lower():
            if 'a' <= char <= 'z':
                char_counts[char] = char_counts.get(char, 0) + 1
        return char_counts

    counts1: dict[str, int] = _normalize(str1)
    counts2: dict[str, int] = _normalize(str2)

    all_keys: list[str] = sorted(list(counts1.keys() | counts2.keys()))

    for key in all_keys:
        if counts1.get(key, 0) != counts2.get(key, 0):
            return False
    return True

