def is_palindromic_number(number: int) -> bool:
    if number < 0:
        return False

    s: str = str(number)
    left: int = 0
    right: int = len(s) - 1

    while left < right:
        if s[left] != s[right]:
            return False
        left += 1
        right -= 1

    return True

def get_palindromes_in_range(start: int, end: int) -> list[int]:
    palindromes: list[int] = []
    for num in range(start, end + 1):
        if is_palindromic_number(num):
            palindromes.append(num)
    return palindromes

def count_palindrome_digits(num: int) -> dict[str, int]:
    s_num: str = str(num)
    digit_counts: dict[str, int] = {}
    for digit in s_num:
        digit_counts[digit] = digit_counts.get(digit, 0) + 1
    return digit_counts

def summarize_palindromes(numbers: list[int]) -> tuple[int, int]:
    total_palindromes: int = len(numbers)
    sum_of_palindromes: int = sum(numbers)
    return total_palindromes, sum_of_palindromes

