def parse_url_params(query_string: str) -> dict[str, str]:
    params: dict[str, str] = {}
    if not query_string:
        return params

    pairs: list[str] = query_string.split('&')
    for pair_str in pairs:
        parts: list[str] = pair_str.split('=', 1)
        if len(parts) == 2:
            key: str = parts[0]
            value: str = parts[1]
            params[key] = value
        elif len(parts) == 1 and parts[0]:
            # Handle cases like 'param_without_value'
            key_only: str = parts[0]
            params[key_only] = ""
    return params

