def multiply_2x2_matrices(matrix_a: list[list[int]], matrix_b: list[list[int]]) -> list[list[int]]:
    """
    Performs matrix multiplication for two 2x2 matrices.
    """
    result_matrix: list[list[int]] = [[0, 0], [0, 0]]

    for i in range(2):
        for j in range(2):
            element_sum: int = 0
            for k in range(2):
                element_sum += matrix_a[i][k] * matrix_b[k][j]
            result_matrix[i][j] = element_sum

    return result_matrix

