from collections import Counter

def find_mode(numbers: list[float | int]) -> float | int:
    if not numbers:
        raise ValueError("Input list cannot be empty.")

    counts: dict[float | int, int] = Counter(numbers)
    max_count: int = 0
    mode: float | int = numbers[0]

    for number, count in counts.items():
        if count > max_count:
            max_count = count
            mode = number

    return mode

