def convert_length(value: float, from_unit: str, to_unit: str) -> float:
    """Converts a length value between meters and feet."""
    METERS_TO_FEET: float = 3.28084
    FEET_TO_METERS: float = 1 / METERS_TO_FEET

    conversion_factors: dict[tuple[str, str], float] = {
        ('m', 'ft'): METERS_TO_FEET,
        ('ft', 'm'): FEET_TO_METERS,
        ('m', 'm'): 1.0,
        ('ft', 'ft'): 1.0,
    }

    key: tuple[str, str] = (from_unit, to_unit)
    if key in conversion_factors:
        return value * conversion_factors[key]
    else:
        raise ValueError("Invalid units specified. Use 'm' or 'ft'.")

def example_usage() -> list[float]:
    results: list[float] = []
    results.append(convert_length(10.0, 'm', 'ft'))
    results.append(convert_length(32.8084, 'ft', 'm'))
    results.append(convert_length(5.0, 'm', 'm'))
    results.append(convert_length(1.0, 'ft', 'ft'))
    return results

if __name__ == '__main__':
    outputs: list[float] = example_usage()
    for res in outputs:
        print(f"{res:.4f}")

def is_even(number: int) -> bool:
    return number % 2 == 0

def process_numbers(numbers: list[int]) -> dict[int, bool]:
    results: dict[int, bool] = {}
    for num in numbers:
        results[num] = is_even(num)
    return results

def get_even_numbers(numbers: list[int]) -> list[int]:
    even_nums: list[int] = []
    for num in numbers:
        if is_even(num):
            even_nums.append(num)
    return even_nums

def analyze_parity(data: tuple[int, ...]) -> dict[str, list[int]]:
    analysis: dict[str, list[int]] = {"even": [], "odd": []}
    for item in data:
        if is_even(item):
            analysis["even"].append(item)
        else:
            analysis["odd"].append(item)
    return analysis

if __name__ == '__main__':
    print(is_even(4))
    print(is_even(7))
    test_list: list[int] = [1, 2, 3, 4, 5, 6]
    print(process_numbers(test_list))
    print(get_even_numbers(test_list))
    test_tuple: tuple[int, int, int] = (10, 11, 12)
    print(analyze_parity(test_tuple))

