class BankAccount:
    def __init__(self, initial_balance: int) -> None:
        self.balance: int = initial_balance

    def deposit(self, amount: int) -> bool:
        if amount > 0:
            self.balance += amount
            return True
        return False

    def withdraw(self, amount: int) -> bool:
        if 0 < amount <= self.balance:
            self.balance -= amount
            return True
        return False

def check_accounts(accounts: list[BankAccount]) -> dict[int, bool]:
    results: dict[int, bool] = {}
    for i, account in enumerate(accounts):
        if account.balance > 0:
            results[i] = True
        else:
            results[i] = False
    return results

def get_total_balance(accounts: list[BankAccount]) -> int:
    total: int = 0
    for account in accounts:
        total += account.balance
    return total

def process_transactions(account: BankAccount, transactions: list[tuple[str, int]]) -> list[bool]:
    transaction_results: list[bool] = []
    for transaction_type, amount in transactions:
        if transaction_type == "deposit":
            transaction_results.append(account.deposit(amount))
        elif transaction_type == "withdraw":
            transaction_results.append(account.withdraw(amount))
        else:
            transaction_results.append(False)
    return transaction_results

