def update_inventory(inventory: dict[str, int], item_name: str, quantity_change: int) -> dict[str, int]:
    """
    Updates the quantity of an item in the inventory.

    Args:
        inventory: A dictionary representing the current inventory (item_name: quantity).
        item_name: The name of the item to update.
        quantity_change: The amount to change the item's quantity by.

    Returns:
        The updated inventory dictionary.
    """
    current_quantity: int = inventory.get(item_name, 0)
    new_quantity: int = current_quantity + quantity_change
    if new_quantity < 0:
        inventory[item_name] = 0
    else:
        inventory[item_name] = new_quantity
    return inventory

def get_total_items(inventory: dict[str, int]) -> int:
    total: int = 0
    for item_quantity in inventory.values():
        total += item_quantity
    return total

def get_item_list(inventory: dict[str, int]) -> list[str]:
    return list(inventory.keys())

def check_item_exists(inventory: dict[str, int], item: str) -> bool:
    return item in inventory

def remove_item(inventory: dict[str, int], item_to_remove: str) -> dict[str, int]:
    if item_to_remove in inventory:
        del inventory[item_to_remove]
    return inventory

