import math

def geometric_mean(numbers: list[float | int]) -> float:
    if not numbers:
        return 0.0

    product: float = 1.0
    for num in numbers:
        if num <= 0:
            return 0.0
        product *= num

    return product**(1/len(numbers))

def _calculate_mean_of_pairs(data: dict[str, list[float]]) -> dict[str, float]:
    results: dict[str, float] = {}
    for key, val_list in data.items():
        if len(val_list) == 2:
            results[key] = geometric_mean(val_list)
        else:
            results[key] = 0.0
    return results

if __name__ == '__main__':
    test_cases: list[tuple[list[float], float]] = [
        ([1.0, 2.0, 4.0], 2.0),
        ([2.0, 8.0], 4.0),
        ([], 0.0),
        ([1.0, -2.0, 4.0], 0.0),
        ([0.0, 2.0, 4.0], 0.0),
        ([1, 1, 1], 1.0),
        ([3, 3, 3], 3.0),
        ([100], 100.0)
    ]

    for input_list, expected_output in test_cases:
        actual_output: float = geometric_mean(input_list)
        assert actual_output == expected_output, f"Input: {input_list}, Expected: {expected_output}, Got: {actual_output}"
        print(f"Test passed for {input_list}")

