        "A": [1.0, 9.0],
        "B": [2.0, 3.0, 4.0],
        "C": [16.0, 4.0],
        "D": []
    }
    pair_means: dict[str, float] = _calculate_mean_of_pairs(example_data)
    print(f"Geometric means of pairs: {pair_means}")

