def convert_temperature(value: float, unit_from: str, unit_to: str) -> float:
    conversions_to_k: dict[str, tuple[float, float]] = {
        'C': (1.0, 273.15),
        'F': (5/9, 459.67),
        'K': (1.0, 0.0)
    }
    conversions_from_k: dict[str, tuple[float, float]] = {
        'C': (1.0, -273.15),
        'F': (9/5, -459.67),
        'K': (1.0, 0.0)
    }

    factor_to_k, offset_to_k = conversions_to_k[unit_from]
    kelvin_value: float = (value + offset_to_k) * factor_to_k

    factor_from_k, offset_from_k = conversions_from_k[unit_to]
    result: float = (kelvin_value * factor_from_k) + offset_from_k

    return result

def common_keys(dict1: dict[str, int], dict2: dict[str, int]) -> set[str]:
    """
    Finds common keys between two dictionaries.

    Args:
        dict1: The first dictionary.
        dict2: The second dictionary.

    Returns:
        A set containing keys present in both dictionaries.
    """
    keys1: set[str] = set(dict1.keys())
    keys2: set[str] = set(dict2.keys())
    return keys1.intersection(keys2)

def main() -> None:
    d1: dict[str, int] = {'a': 1, 'b': 2, 'c': 3}
    d2: dict[str, int] = {'b': 3, 'c': 4, 'd': 5}
    d3: dict[str, int] = {'x': 10}
    d4: dict[str, int] = {'y': 20}

    result1: set[str] = common_keys(d1, d2)
    print(f"Common keys between {d1} and {d2}: {result1}")

    result2: set[str] = common_keys(d3, d4)
    print(f"Common keys between {d3} and {d4}: {result2}")

    result3: set[str] = common_keys({'apple': 1, 'banana': 2}, {'banana': 3, 'orange': 4})
    print(f"Common keys between {{'apple': 1, 'banana': 2}} and {{'banana': 3, 'orange': 4}}: {result3}")

if __name__ == '__main__':
    main()

