    for i in range(n_val):
        squares.append(i * i)
    return tuple(squares)

def sum_perfect_squares(nums: list[int]) -> int:
    total_sum: int = 0
    for num in nums:
        if is_perfect_square(num):
            total_sum += num
    return total_sum

