import re

def simple_calculator(expression: str) -> int:
    """
    Parses a simple arithmetic expression involving addition and subtraction
    of positive integers and returns the integer result.
    """
    parts: list[str] = re.split(r'([+\-])', expression)

    if not parts or len(parts) < 3:
        raise ValueError("Invalid expression format")

    numbers: list[int] = [int(p) for p in parts[::2]]
    operators: list[str] = parts[1::2]

    if not numbers:
        raise ValueError("No numbers found in expression")

    result: int = numbers[0]
    for i, op in enumerate(operators):
        if op == '+':
            result += numbers[i + 1]
        elif op == '-':
            result -= numbers[i + 1]
        else:
            raise ValueError(f"Unsupported operator: {op}")

    return result

