import math

def calculate_median(numbers: list[float]) -> float | None:
    if not numbers:
        return None

    sorted_numbers: list[float] = sorted(numbers)
    n: int = len(sorted_numbers)

    if n % 2 == 1:
        middle_index: int = n // 2
        return float(sorted_numbers[middle_index])
    else:
        mid_right_index: int = n // 2
        mid_left_index: int = mid_right_index - 1
        middle_elements: tuple[float, float] = (sorted_numbers[mid_left_index], sorted_numbers[mid_right_index])
        return sum(middle_elements) / 2.0

