def is_valid_us_phone_number(phone_number: str) -> bool:
    """
    Validates a US phone number format.
    Accepts 10 digits, optionally with hyphens or spaces.
    """
    cleaned_digits: list[str] = [char for char in phone_number if char.isdigit()]

    if len(cleaned_digits) != 10:
        return False

    original_chars: list[str] = list(phone_number)
    digit_indices: list[int] = []

    for i, char in enumerate(original_chars):
        if char.isdigit():
            digit_indices.append(i)
        elif char not in ['-', ' ']:
            return False

    # Check non-digit characters are only hyphens or spaces in valid positions
    # This part helps to exclude cases like '123(456)7890' even if length is 10
    allowed_non_digit_positions: list[int] = [3, 7]
    for i in range(len(original_chars)):
        if not original_chars[i].isdigit():
            # Check if non-digit characters are only hyphens or spaces
            if original_chars[i] not in ['-', ' ']:
                return False
            # If there are non-digits, they should appear at expected places
            # for 10-digit sequence (e.g. 123-456-7890 or 123 456 7890)
            if i not in allowed_non_digit_positions and (i - 1) not in allowed_non_digit_positions:
                return False

    # Additional check to ensure hyphens/spaces are consistently applied or not at all
    # This prevents '123-456 7890' (mixed delimiters)
    delimiters: list[str] = [c for c in phone_number if c in ['-', ' ']]
    if len(delimiters) > 0 and not all(d == delimiters[0] for d in delimiters):
        return False

    return True

