def join_path_components(components: list[str]) -> str:
    cleaned_components: list[str] = []
    for component in components:
        if component:
            cleaned_components.append(component.strip('/'))

    if not cleaned_components:
        return ""

    if components[0] == '/':
        return '/' + '/'.join(s for s in cleaned_components if s)
    else:
        return '/'.join(s for s in cleaned_components if s)

def _process_path_segment(segment: str) -> str:
    return segment.strip('/')

def _construct_final_path(segments: list[str], is_absolute: bool) -> str:
    filtered_segments: list[str] = [s for s in segments if s]
    if is_absolute:
        return '/' + '/'.join(filtered_segments)
    else:
        return '/'.join(filtered_segments)

def join_path_components_alternative(components: list[str]) -> str:
    if not components:
        return ""

    processed_segments: list[str] = [_process_path_segment(c) for c in components if c is not None]
    is_absolute_path: bool = components[0] == '/'

    return _construct_final_path(processed_segments, is_absolute_path)

