import collections

def find_most_frequent_element(elements: list[object]) -> object | None:
    if not elements:
        return None

    counts: dict[object, int] = collections.defaultdict(int)
    for element in elements:
        counts[element] += 1

    max_count: int = -1
    most_frequent_element: object | None = None

    for element, count in counts.items():
        if count > max_count:
            max_count = count
            most_frequent_element = element

    return most_frequent_element

