class Node:
    def __init__(self, value: int, left: 'Node' = None, right: 'Node' = None) -> None:
        self.value: int = value
        self.left: Node | None = left
        self.right: Node | None = right

def is_symmetric(root: Node | None) -> bool:
    if not root:
        return True

    def _is_mirror(node1: Node | None, node2: Node | None) -> bool:
        if not node1 and not node2:
            return True
        if not node1 or not node2 or node1.value != node2.value:
            return False
        return _is_mirror(node1.left, node2.right) and _is_mirror(node1.right, node2.left)

    return _is_mirror(root.left, root.right)

def build_tree_from_list(values: list[int | None]) -> Node | None:
    if not values:
        return None
    nodes: list[Node | None] = [Node(val) if val is not None else None for val in values]
    root: Node | None = nodes[0]
    q: list[tuple[Node, int]] = [(root, 0)] if root else []
    head: int = 0
    while head < len(q):
        current_node, i = q[head]
        head += 1
        if not current_node:
            continue
        left_idx: int = 2 * i + 1
        right_idx: int = 2 * i + 2
        if left_idx < len(nodes):
            current_node.left = nodes[left_idx]
            if nodes[left_idx]:
                q.append((nodes[left_idx], left_idx))
        if right_idx < len(nodes):
            current_node.right = nodes[right_idx]
            if nodes[right_idx]:
                q.append((nodes[right_idx], right_idx))
    return root

