def parse_args(args_list: list[str]) -> dict[str, str | bool]:
    """
    Parses a list of command-line argument strings into a dictionary.
    Arguments are in the format `--key value` or `--flag`.
    Flags without a value should have `True` as their value.
    """
    result: dict[str, str | bool] = {}
    i: int = 0
    while i < len(args_list):
        arg: str = args_list[i]
        if arg.startswith('--'):
            key: str = arg[2:]
            if i + 1 < len(args_list) and not args_list[i + 1].startswith('--'):
                result[key] = args_list[i + 1]
                i += 2
            else:
                result[key] = True
                i += 1
        else:
            # Handle non-key arguments if necessary, though example implies only key-value/flags
            i += 1
    return result

